const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define location and dates
  const lakePoint = ee.Geometry.Point([-71.6, -40.3]); // Lago Hermoso coordinates
  const region = lakePoint.buffer(1000); // 1km buffer

  // Date ranges (±1 day for flexibility)
  const date1987 = ee.Date('1987-03-29');
  const range1987 = ee.DateRange(date1987.advance(-1, 'day'), date1987.advance(1, 'day'));
  const date2001 = ee.Date('2001-02-15');
  const range2001 = ee.DateRange(date2001.advance(-1, 'day'), date2001.advance(1, 'day'));

  // 2. Function to get cloud percentage from Landsat
  function getCloudStats(collection, dateRange) {
    const col = collection.filterBounds(region).filterDate(dateRange);
    const count = col.size();
    const img = col.first(); // Get most recent image in range

    // If no images, return null
    if (count.getInfo() === 0) return null;

    // Use cloud cover property from Landsat metadata
    const cloudPercent = img.get('CLOUD_COVER');
    return {
      count: count.getInfo(),
      cloudPercent: ee.Number(cloudPercent).getInfo()
    };
  }

  // 3. Get data - Landsat 5 for 1987, Landsat 7 for 2001
  const stats1987 = getCloudStats(ee.ImageCollection('LANDSAT/LT05/C02/T1_TOA'), range1987);
  const stats2001 = getCloudStats(ee.ImageCollection('LANDSAT/LE07/C02/T1_TOA'), range2001);

  // 4. Handle missing data cases
  if (!stats1987 || !stats2001) {
    console.log(`1987 Images: ${stats1987 ? stats1987.count : 0}`);
    console.log(`2001 Images: ${stats2001 ? stats2001.count : 0}`);
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Validate cloud percentage values (0-100 reasonable range)
  const pct1987 = stats1987.cloudPercent;
  const pct2001 = stats2001.cloudPercent;

  if (pct1987 === null || pct2001 === null || 
      pct1987 === undefined || pct2001 === undefined ||
      pct1987 < 0 || pct1987 > 100 || pct2001 < 0 || pct2001 > 100) {
    console.log(`1987 Cloud: ${pct1987}%, 2001 Cloud: ${pct2001}%`);
    console.log('<answer>C3</answer>');
    return;
  }

  // 6. Print evidence and determine answer
  console.log(`1987-03-29 Cloud: ${pct1987.toFixed(1)}%`);
  console.log(`2001-02-15 Cloud: ${pct2001.toFixed(1)}%`);

  // Compare cloud cover percentages
  if (pct1987 > pct2001) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
